// function currencySymbol(code) mein string code do
// "INR": "₹", "USD": "$", "EUR": "€", "GBP": "£"
// Unknown: "?"

solution:
function currencySymbol(code) {
  switch (code.toUpperCase()) {
    case "INR": return "₹"
    case "USD": return "$"
    case "EUR": return "€"
    case "GBP": return "£"
    default: return "?"
  }
}
